list_variations.code:
final response = await client.variations
    .listVariations(queryParams: {'search': 'size', 'standard': 'text'});
final body = response.map as Map;
for (final variation in body['variations'] as List) {
  print('${(variation as Map)['id']} ${variation['name']} ${variation['standard']}');
}
print((body['pagination'] as Map)['total']);

